import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cfloat>
#include <vector>
#include <cute/tensor.hpp>

using namespace cute;

constexpr int InnerTile = 32;
constexpr int ReduceThreads = 8;

__global__ void min_reduce_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int outer_size, int reduce_size, int inner_size)
{
  int outer_idx = blockIdx.x;
  int inner_base = blockIdx.y * InnerTile;

  int tx = threadIdx.x; // 0..InnerTile-1
  int ty = threadIdx.y; // 0..ReduceThreads-1

  int inner_idx = inner_base + tx;
  bool valid = inner_idx < inner_size;

  // CuTe tensor view of the (reduce_size, inner_size) slice for this outer index
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)outer_idx * (int64_t)reduce_size * (int64_t)inner_size),
      make_shape(reduce_size, inner_size),
      make_stride(inner_size, Int<1>{})
  );

  float local_min = FLT_MAX;

  if (valid) {
    for (int r = ty; r < reduce_size; r += ReduceThreads) {
      float v = mX(r, inner_idx);
      local_min = min(local_min, v);
    }
  }

  __shared__ float sdata[InnerTile][ReduceThreads];
  sdata[tx][ty] = local_min;
  __syncthreads();

  #pragma unroll
  for (int offset = ReduceThreads / 2; offset > 0; offset >>= 1) {
    if (ty < offset) {
      sdata[tx][ty] = min(sdata[tx][ty], sdata[tx][ty + offset]);
    }
    __syncthreads();
  }

  if (ty == 0 && valid) {
    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)outer_idx * (int64_t)inner_size),
        make_shape(inner_size),
        make_stride(Int<1>{})
    );
    mY(inner_idx) = sdata[tx][0];
  }
}

torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  int ndim = x_c.dim();
  if (dim < 0) dim += ndim;
  TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

  int64_t outer_size = 1;
  for (int i = 0; i < dim; ++i) outer_size *= x_c.size(i);
  int64_t reduce_size = x_c.size(dim);
  int64_t inner_size = 1;
  for (int i = dim + 1; i < ndim; ++i) inner_size *= x_c.size(i);

  std::vector<int64_t> out_shape;
  for (int i = 0; i < ndim; ++i) {
    if (i != dim) out_shape.push_back(x_c.size(i));
  }

  auto y = torch::empty(out_shape, x_c.options());

  dim3 block(InnerTile, ReduceThreads);
  dim3 grid(
      (unsigned)outer_size,
      (unsigned)((inner_size + InnerTile - 1) / InnerTile)
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  min_reduce_kernel<<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer_size, (int)reduce_size, (int)inner_size
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "min_reduce_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["min_reduce_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension using a
    custom CuTe-based CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce_forward(x, self.dim)

