class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension using a
    hand-authored PTX kernel executed through cutegen.ptx_runtime.PtxModule.
    """

    INNER_TILE = 32
    REDUCE_THREADS = 8

    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._module = _get_module()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        ndim = x_c.dim()
        dim = self.dim
        if dim < 0:
            dim += ndim
        assert 0 <= dim < ndim, "dim out of range"

        outer_size = 1
        for i in range(dim):
            outer_size *= x_c.shape[i]
        reduce_size = x_c.shape[dim]
        inner_size = 1
        for i in range(dim + 1, ndim):
            inner_size *= x_c.shape[i]

        out_shape = [x_c.shape[i] for i in range(ndim) if i != dim]
        y = torch.empty(out_shape, device=x_c.device, dtype=x_c.dtype)

        block = (self.INNER_TILE, self.REDUCE_THREADS, 1)
        grid = (
            int(outer_size),
            int((inner_size + self.INNER_TILE - 1) // self.INNER_TILE),
            1,
        )
        shared_mem_bytes = self.INNER_TILE * self.REDUCE_THREADS * 4

        stream = torch.cuda.current_stream().cuda_stream

        self._module.launch(
            "min_reduce_kernel",
            grid=grid,
            block=block,
            shared_mem=shared_mem_bytes,
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(y.data_ptr()),
                i32(int(outer_size)),
                i32(int(reduce_size)),
                i32(int(inner_size)),
            ],
        )

        return y
